// Arduino Sketch
// Назначаем пины для светодиодов
const int PIN_RED = 11;
const int PIN_YELLOW = 10;
const int PIN_GREEN = 9;

void setup() {
  // Настраиваем пины как выходы
  pinMode(PIN_RED, OUTPUT);
  pinMode(PIN_YELLOW, OUTPUT);
  pinMode(PIN_GREEN, OUTPUT);

  // Сразу выключаем все светодиоды на старте
  digitalWrite(PIN_RED, LOW);
  digitalWrite(PIN_YELLOW, LOW);
  digitalWrite(PIN_GREEN, LOW);
}

void loop() {
  // 1. Красный горит 5 секунд
  digitalWrite(PIN_RED, HIGH);
  digitalWrite(PIN_YELLOW, LOW);
  digitalWrite(PIN_GREEN, LOW);
  delay(5000);

  // 2. Красный + жёлтый (переход к зелёному) — 2 секунды
  digitalWrite(PIN_YELLOW, HIGH);
  delay(2000);

  // 3. Зелёный горит 5 секунд
  digitalWrite(PIN_RED, LOW);
  digitalWrite(PIN_YELLOW, LOW);
  digitalWrite(PIN_GREEN, HIGH);
  delay(5000);

  // 4. Мигающий зелёный (3 раза по 0.5 сек)
  for (int i = 0; i < 3; i++) {
    digitalWrite(PIN_GREEN, LOW);
    delay(500);
    digitalWrite(PIN_GREEN, HIGH);
    delay(500);
  }

  // 5. Жёлтый горит 3 секунды
  digitalWrite(PIN_GREEN, LOW);
  digitalWrite(PIN_YELLOW, HIGH);
  delay(3000);

  // Дальше цикл повторяется автоматически
}
